(function(root){function distance(a,b){const r=Math.PI/180,dlat=(b.lat-a.lat)*r,dlon=(b.lon-a.lon)*r,h=Math.sin(dlat/2)**2+Math.cos(a.lat*r)*Math.cos(b.lat*r)*Math.sin(dlon/2)**2;return 6371e3*2*Math.atan2(Math.sqrt(h),Math.sqrt(Math.max(0,1-h)))}function accept(point,last,now=Date.now()){if(![point.lat,point.lon,point.accuracy,point.time].every(Number.isFinite)||Math.abs(point.lat)>90||Math.abs(point.lon)>180||point.accuracy<0)return{ok:!1,reason:"Coordenadas no v\xE1lidas"};if(point.accuracy>50)return{ok:!1,reason:"Se\xF1al imprecisa. Esperando precisi\xF3n de 50 m o mejor."};if(Math.abs(now-point.time)>15e3)return{ok:!1,reason:"Posici\xF3n antigua. Esperando una lectura nueva."};if(!last)return{ok:!0,meters:0};const dt=(point.time-last.time)/1e3;if(dt<=0)return{ok:!1,reason:"Esperando una lectura nueva."};if(dt>30)return{ok:!0,meters:0,break:!0};const meters=distance(last,point);return meters/dt>35?{ok:!1,reason:"Salto de posici\xF3n descartado."}:meters<Math.max(5,Math.min(15,(point.accuracy+last.accuracy)/4))?{ok:!1,reason:"Se\xF1al recibida. Sin desplazamiento significativo."}:{ok:!0,meters}}function segments(points){const list=[];for(const p of points)(!list.length||p.break)&&list.push([]),list.at(-1).push(p);return list}function gpx(route){return'<?xml version="1.0" encoding="UTF-8"?><gpx version="1.1" creator="CAFAS" xmlns="http://www.topografix.com/GPX/1/1"><trk><name>Ruta CAFAS</name>'+segments(route.points).map(s=>"<trkseg>"+s.map(p=>`<trkpt lat="${p.lat}" lon="${p.lon}"><time>${new Date(p.time).toISOString()}</time></trkpt>`).join("")+"</trkseg>").join("")+"</trk></gpx>"}const api={distance,accept,segments,gpx};typeof module<"u"?module.exports=api:root.GPSCore=api})(globalThis);
